--
-- Disparadores `customer`
--
DELIMITER $$
CREATE TRIGGER `customer_create_date` BEFORE INSERT ON `customer` FOR EACH ROW SET NEW.create_date = NOW()
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Estructura Stand-in para la vista `customer_list`
-- (Véase abajo para la vista actual)
--
CREATE TABLE `customer_list` (
`ID` smallint(5) unsigned
,`name` varchar(91)
,`address` varchar(50)
,`zip code` varchar(10)
,`phone` varchar(20)
,`city` varchar(50)
,`country` varchar(50)
,`notes` varchar(6)
,`SID` tinyint(3) unsigned
);

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `film`
--

CREATE TABLE `film` (
  `film_id` smallint(5) UNSIGNED NOT NULL,
  `title` varchar(128) NOT NULL,
  `description` text DEFAULT NULL,
  `release_year` year(4) DEFAULT NULL,
  `language_id` tinyint(3) UNSIGNED NOT NULL,
  `original_language_id` tinyint(3) UNSIGNED DEFAULT NULL,
  `rental_duration` tinyint(3) UNSIGNED NOT NULL DEFAULT 3,
  `rental_rate` decimal(4,2) NOT NULL DEFAULT 4.99,
  `length` smallint(5) UNSIGNED DEFAULT NULL,
  `replacement_cost` decimal(5,2) NOT NULL DEFAULT 19.99,
  `rating` enum('G','PG','PG-13','R','NC-17') DEFAULT 'G',
  `special_features` set('Trailers','Commentaries','Deleted Scenes','Behind the Scenes') DEFAULT NULL,
  `last_update` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `film`
--

INSERT INTO `film` (`film_id`, `title`, `description`, `release_year`, `language_id`, `original_language_id`, `rental_duration`, `rental_rate`, `length`, `replacement_cost`, `rating`, `special_features`, `last_update`) VALUES
(1, 'Tenet', 'A covert operative learns to manipulate the flow of time as he races to prevent a future attack.', '2020', 1, NULL, 3, 4.99, 150, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(2, 'Soul', 'A middle school music teacher lands the gig of a lifetime and then falls down a manhole into the world before life.', '2020', 1, NULL, 3, 3.99, 100, 24.99, 'PG', NULL, '2026-10-19 17:15:18'),
(3, 'Nomadland', 'A widow leaves her town behind and journeys through the American West as a modern day nomad.', '2020', 1, NULL, 3, 2.99, 107, 19.99, 'R', NULL, '2026-10-19 17:15:18'),
(4, 'The Trial of the Chicago 7', 'Seven anti war activists are charged with conspiracy after protests explode into violence in 1968.', '2020', 1, NULL, 3, 4.99, 130, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(5, 'Promising Young Woman', 'A former medical student haunted by a tragedy sets out to exact revenge on those who got away with it.', '2020', 1, NULL, 3, 3.99, 113, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(6, 'Minari', 'A Korean American family moves to a small Arkansas farm in search of its own version of the American dream.', '2020', 1, NULL, 3, 3.99, 115, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(7, 'Sound of Metal', 'A punk metal drummer suddenly loses his hearing and must learn to live in complete silence.', '2020', 1, NULL, 3, 3.99, 120, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(8, 'The Father', 'An elderly man struggling with memory loss questions reality while his daughter tries to arrange care for him.', '2020', 1, NULL, 3, 3.99, 97, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(9, 'Onward', 'Two elf brothers set out on a quest for a lost spell that will let them share one last day with their father.', '2020', 1, NULL, 3, 3.99, 102, 24.99, 'PG', NULL, '2026-10-19 17:15:18'),
(10, 'Bad Boys for Life', 'Miami detectives Mike and Marcus reunite for one last case when a vengeful cartel comes after them.', '2020', 1, NULL, 3, 4.99, 124, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(11, 'Sonic the Hedgehog', 'A superfast blue hedgehog hides in a small town and teams up with a local cop to stop a mad scientist.', '2020', 1, NULL, 3, 3.99, 99, 24.99, 'PG', NULL, '2026-10-19 17:15:18'),
(12, 'The Invisible Man', 'A woman escapes an abusive relationship only to find herself stalked by a threat nobody else can see.', '2020', 1, NULL, 3, 3.99, 124, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(13, 'Emma.', 'A clever young woman in Regency England busies herself with matchmaking for everyone except herself.', '2020', 1, NULL, 3, 2.99, 124, 19.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(14, 'Mank', 'Screenwriter Herman Mankiewicz races to finish Citizen Kane while feuding with Orson Welles and Hollywood power brokers.', '2020', 1, NULL, 3, 3.99, 131, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(15, 'News of the World', 'A Civil War veteran agrees to return a kidnapped girl to her family across hundreds of miles of hostile frontier.', '2020', 1, NULL, 3, 3.99, 118, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(16, 'Da 5 Bloods', 'Vietnam veterans return to the jungle to recover the body of their fallen squad leader and a hidden fortune in gold.', '2020', 1, NULL, 3, 4.99, 154, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(17, 'Hamilton', 'The life of Alexander Hamilton, founding father of the United States, told through a groundbreaking hip hop score.', '2020', 1, NULL, 3, 4.99, 160, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(18, 'First Cow', 'Two travelers in the Oregon Territory form a friendship and start a small business selling fried cakes.', '2020', 1, NULL, 3, 2.99, 122, 19.99, 'R', NULL, '2026-10-19 17:15:18'),
(19, 'The Way Back', 'A former basketball star haunted by addiction is pulled back to coach the team of his old high school.', '2020', 1, NULL, 3, 3.99, 108, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(20, 'Dune', 'The heir of a noble family must travel to the most dangerous planet in the universe to secure the future of his people.', '2021', 1, NULL, 3, 4.99, 155, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(21, 'No Time to Die', 'Bond has left active service and is pulled back to rescue a kidnapped scientist from a villain armed with a new weapon.', '2021', 1, NULL, 3, 4.99, 163, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(22, 'West Side Story', 'Two rival gangs clash on the streets of 1950s New York while two young lovers try to bridge the divide.', '2021', 1, NULL, 3, 4.99, 156, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(23, 'The Power of the Dog', 'A ruthless cattleman feels threatened when his brother marries a widowed innkeeper and her sensitive son.', '2021', 1, NULL, 3, 3.99, 126, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(24, 'CODA', 'The only hearing member of a deaf family must choose between her dream of music and helping her parents fishing business.', '2021', 1, NULL, 3, 3.99, 111, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(25, 'Belfast', 'A young boy comes of age amid the political turmoil of late 1960s Northern Ireland.', '2021', 1, NULL, 3, 3.99, 98, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(26, 'Licorice Pizza', 'A teenage actor and a young woman navigate first love and small time schemes in 1970s Southern California.', '2021', 1, NULL, 3, 3.99, 133, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(27, 'Nightmare Alley', 'An ambitious carny with a talent for manipulation teams up with a psychiatrist far more dangerous than himself.', '2021', 1, NULL, 3, 3.99, 150, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(28, 'The French Dispatch', 'The final issue of an American magazine in a fictional French city assembles the field reports of its writers.', '2021', 1, NULL, 3, 3.99, 107, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(29, 'The Green Knight', 'Young Gawain embarks on a daring quest to confront a mysterious green stranger and prove his worth.', '2021', 1, NULL, 3, 3.99, 129, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(30, 'Last Night in Soho', 'A fashion student is pulled into 1960s London where the story of a glamourous singer turns nightmarish.', '2021', 1, NULL, 3, 3.99, 116, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(31, 'Spencer', 'Over one Christmas weekend at the Sandringham estate, Princess Diana decides to leave the royal family.', '2021', 1, NULL, 3, 3.99, 117, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(32, 'House of Gucci', 'The ambitious Patrizia Reggiani marries into the Gucci dynasty and triggers a brutal battle for the fashion house.', '2021', 1, NULL, 3, 4.99, 158, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(33, 'Don\'t Look Up', 'Two astronomers go on a media tour to warn mankind of a planet killing comet hurtling toward Earth.', '2021', 1, NULL, 3, 3.99, 138, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(34, 'The Matrix Resurrections', 'Neo is pulled back into the Matrix to face a new threat that ties his past to the fate of the whole world.', '2021', 1, NULL, 3, 4.99, 148, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(35, 'Shang-Chi and the Legend of the Ten Rings', 'A master of martial arts is drawn into a plot by a mysterious organization and by his own father.', '2021', 1, NULL, 3, 4.99, 132, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(36, 'Free Guy', 'A bank teller discovers he is a background character in a video game and decides to become the hero.', '2021', 1, NULL, 3, 3.99, 115, 24.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(37, 'The Last Duel', 'In 14th century France a squire and a knight face each other in trial by combat over a womans testimony.', '2021', 1, NULL, 3, 3.99, 152, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(38, 'Drive My Car', 'A widowed stage director forms an unexpected bond with the young woman assigned to be his driver.', '2021', 1, 3, 3, 2.99, 179, 19.99, 'R', NULL, '2026-10-19 17:15:18'),
(39, 'The Tragedy of Macbeth', 'A Scottish general is consumed by ambition and blood after witches prophesy that he will be king.', '2021', 1, NULL, 3, 3.99, 105, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
(40, 'Top Gun: Maverick', 'After decades as a test pilot, Maverick must train a group of elite graduates for a mission that demands everything.', '2022', 1, NULL, 3, 4.99, 130, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(41, 'Avatar: The Way of Water', 'The Sully family seeks refuge on an ocean moon and fights to protect its new home from a returning threat.', '2022', 1, NULL, 3, 4.99, 192, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(42, 'Everything Everywhere All at Once', 'A laundromat owner discovers she must connect with parallel versions of herself to save the multiverse.', '2022', 1, NULL, 3, 4.99, 139, 29.99, 'R', NULL, '2026-10-19 17:15:18'),
(43, 'The Batman', 'Batman ventures into the Gotham underworld when a sadistic killer leaves a trail of cryptic clues.', '2022', 1, NULL, 3, 4.99, 176, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(44, 'Elvis', 'The life of Elvis Presley rises from poverty to stardom under the control of his manager Colonel Tom Parker.', '2022', 1, NULL, 3, 4.99, 159, 29.99, 'PG-13', NULL, '2026-10-19 17:15:18'),
(45, 'Tar', 'A legendary conductor at the peak of her career faces questions about power, accountability and her own past.', '2022', 1, NULL, 3, 3.99, 158, 24.99, 'R', NULL, '2026-10-19 17:15:18'),
