--
-- Estructura Stand-in para la vista `sales_by_film_category`
-- (Véase abajo para la vista actual)
--
CREATE TABLE `sales_by_film_category` (
`category` varchar(25)
,`total_sales` decimal(27,2)
);

-- --------------------------------------------------------

--
-- Estructura Stand-in para la vista `sales_by_store`
-- (Véase abajo para la vista actual)
--
